<#
================================================================================
 goad-elk-agent  --  Sysmon + Winlogbeat 7.17.6 for ONE Windows lane host
================================================================================

 WHAT THIS IS
   The Windows agent half of GOAD's `elk` extension, ported from
   GOAD-main/extensions/elk/ansible/roles/logs_windows:
       defaults/main.yml            -> the versions and paths below
       tasks/main.yml               -> the Sysmon install
       tasks/winlogbeat.yml         -> the Winlogbeat install
       templates/winlogbeat.yml.j2  -> the config rendered below
   It installs Sysmon with the SwiftOnSecurity config and Winlogbeat 7.17.6,
   and points Winlogbeat at the lane's own ELK box.

 WHY THIS RUNS PER LANE INSTEAD OF BEING BAKED INTO A TEMPLATE
   The Windows templates (Server / Windows 11) are SHARED by every GOAD lab on
   this platform, not just blue-team lanes. A bad bake would break every course
   at once. Worse, an agent that is snapshotted AFTER it has registered bakes
   ONE agent identity into every clone, and the SIEM then sees a single agent
   flapping across every lane simultaneously. Installing here, at post-clone
   time, means: zero blast radius on the shared images, per-engagement opt-in, a
   fresh and correct enrolment every time, a version that changes by editing
   this file rather than by re-baking, and visible per-script status in the
   deployment UI instead of a silently agent-less golden image.

 VERSION: 7.17.6 -- STAY ON 7.x. DO NOT CASUALLY BUMP THIS TO 8.x.
   GOAD pins Elasticsearch 7.x and winlogbeat 7.17.6, and those are
   self-consistent: the extension ships a 7.x-shaped elasticsearch.yml with NO
   security stanza. Elasticsearch 8 secures by default, so an 8.x pairing fails
   in a way that presents as "Kibana is down" rather than as a version
   mismatch. The sealed ELK template was sealed from a 7.x staging lab and
   carries the winlogbeat-7.17.6 index template. Match it.

 THIS SCRIPT DELIBERATELY DOES NOT RUN `winlogbeat setup`, AND DOES NOT REBOOT.
   THAT IS NOT AN OMISSION. DO NOT "FIX" IT.
   Upstream's tasks/main.yml reboots each Windows host and then runs
   `winlogbeat setup -e` on it, with no run_once -- so identical GLOBAL work
   (index templates, ILM policy, Kibana dashboards) is repeated 3-4 times per
   lane, after 3-4 reboots. The ELK golden template was SEALED FROM A STAGING
   LAB precisely so that work is already inside the image: the seal script
   (seal-goad-elk-template.sh) refuses to seal a box whose winlogbeat index
   template and Kibana saved objects are missing. Installing the service and
   starting it is therefore sufficient, and the reboot -- which would knock
   lane VMs over in the middle of a deploy -- is pure cost.

 NO CREDENTIALS ARE EMITTED, ON PURPOSE.
   The upstream template hardcodes elastic/changeme. That only works with
   security ON and the default password unchanged, i.e. never. GOAD's stack is
   7.x with security off, so sending an Authorization header at all is wrong.

 IT TARGETS A NAME, NOT AN IP.
   output.elasticsearch.hosts points at elk.cybercore.lan, which the lane
   gateway publishes as a dnsmasq host-record for the lane's own `elk` machine
   -- the same record the loggen sensor's baked agent already resolves.
   Upstream pins elk at .50 and CyberCore addresses it at .24; a name means
   those two never have to agree.

 NO ARGUMENTS, NO SECRETS.
   script_args is interpolated UNQUOTED onto the command line by
   script-executor.js, so nothing may ever be passed through it. This script
   needs nothing passed in, which is the correct answer to that trap.

 EXIT CODE CONTRACT
   Exits 0 when the agents are installed, EVEN IF ELK IS NOT ANSWERING YET.
   Post-clone scripts routinely run before the lane's ELK VM has finished
   booting, and winlogbeat retries its output connection forever on its own, so
   "cannot connect yet" is a normal transient state and not a failed lane. It
   is logged and moved past. Exits 1 only when a component could not be
   INSTALLED at all (e.g. a download that never succeeded) -- a real,
   actionable failure that executeScriptsOnVM records per-script without
   aborting the deploy, which is exactly the visibility this design exists for.
================================================================================
#>

$ErrorActionPreference = 'Continue'
# Invoke-WebRequest's progress bar costs more than the download itself when the
# console is being scraped through the guest agent.
$ProgressPreference = 'SilentlyContinue'

# --- Everything the upstream role's defaults/main.yml pins -------------------
$WinlogbeatVersion = '7.17.6'
$ElkHost           = 'elk.cybercore.lan'
$ElkPort           = 9200
$InstallRoot       = 'C:\Program Files\Elastic\winlogbeat'
$VersionDirName    = "winlogbeat-$WinlogbeatVersion-windows-x86_64"
$VersionDir        = Join-Path $InstallRoot $VersionDirName
$BeatUrl           = "https://artifacts.elastic.co/downloads/beats/winlogbeat/$VersionDirName.zip"
$SysmonDir         = 'C:\sysmon'
$SysmonZipUrl      = 'https://download.sysinternals.com/files/Sysmon.zip'
$SysmonConfigPath  = Join-Path $SysmonDir 'sysmonconfig-export.xml'

$script:Failures = @()

function Write-Step { param([string]$Message) Write-Host ''; Write-Host "==> $Message" }
function Write-Info { param([string]$Message) Write-Host "    $Message" }
function Write-Note { param([string]$Message) Write-Host "    NOTE: $Message" }
function Add-Failure {
    param([string]$Message)
    $script:Failures += $Message
    Write-Host "    ERROR: $Message"
}

# Download with retries. Both CDNs occasionally 503 when a rack of lanes comes
# up at once.
function Get-RemoteFile {
    param([string]$Url, [string]$OutFile, [int]$Retries = 3)
    for ($i = 1; $i -le $Retries; $i++) {
        try {
            Write-Info "GET $Url  (attempt $i of $Retries)"
            Invoke-WebRequest -Uri $Url -OutFile $OutFile -UseBasicParsing -TimeoutSec 600
            $len = (Get-Item $OutFile -ErrorAction SilentlyContinue).Length
            Write-Info "downloaded $len bytes -> $OutFile"
            return $true
        } catch {
            Write-Note "download failed: $($_.Exception.Message)"
            Start-Sleep -Seconds 5
        }
    }
    return $false
}

# A short, bounded TCP probe. Test-NetConnection can sit for 20+ seconds
# against a host that is still booting, and this is only ever informational.
function Test-TcpPort {
    param([string]$HostName, [int]$Port, [int]$TimeoutMs = 5000)
    $client = $null
    try {
        $client = New-Object System.Net.Sockets.TcpClient
        $iar = $client.BeginConnect($HostName, $Port, $null, $null)
        $done = $iar.AsyncWaitHandle.WaitOne($TimeoutMs, $false)
        if ($done -and $client.Connected) { $client.EndConnect($iar); return $true }
        return $false
    } catch {
        return $false
    } finally {
        if ($client) { $client.Close() }
    }
}

Write-Host '=========================================================='
Write-Host ' goad-elk-agent : Sysmon + Winlogbeat (per-lane install)'
Write-Host '=========================================================='
Write-Info "Host        : $env:COMPUTERNAME"
Write-Info "OS          : $((Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue).Caption)"
Write-Info "Winlogbeat  : $WinlogbeatVersion"
Write-Info "ELK output  : ${ElkHost}:${ElkPort}"
Write-Info "Started     : $(Get-Date -Format 'u')"

# TLS 1.2. Older Server SKUs still negotiate TLS 1.0 by default and both CDNs
# refuse it, which surfaces as "the underlying connection was closed".
try {
    [Net.ServicePointManager]::SecurityProtocol =
        [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
} catch { Write-Note "could not raise TLS version: $($_.Exception.Message)" }

# ============================================================================
# 1. SYSMON CONFIGURATION
# ============================================================================
# The SwiftOnSecurity config is EMBEDDED as base64 rather than fetched from
# GitHub. Upstream ships it as a role FILE (files/sysmonconfig-export.xml) and
# these bytes are that exact file, so the install is reproducible and does not
# depend on raw.githubusercontent.com being reachable from inside a lane. The
# BINARY (Sysmon.zip, ~3 MB) is downloaded from Microsoft instead -- embedding
# a binary is not worth a 4 MB script.
#
# Written with WriteAllBytes so the upstream file is reproduced byte for byte,
# BOM included, and parsed by Sysmon exactly as upstream parses it.
#
# Upstream copies this config UNCONDITIONALLY (win_copy) and only guards the
# INSTALL on the service already existing. Same here.
Write-Step 'Writing Sysmon configuration'
if (-not (Test-Path $SysmonDir)) {
    New-Item -ItemType Directory -Path $SysmonDir -Force | Out-Null
}
