bWU9IiIgZ3JvdXBSZWxhdGlvbj0ib3IiPgoJCTxQcm9jZXNzVGFtcGVyaW5nIG9ubWF0Y2g9ImV4Y2x1ZGUiPgoJCQk8SW1hZ2UgY29uZGl0aW9uPSJiZWdp
biB3aXRoIj5DOlxQcm9ncmFtIEZpbGVzICh4ODYpXE1pY3Jvc29mdFxFZGdlXEFwcGxpY2F0aW9uXDwvSW1hZ2U+CgkJPC9Qcm9jZXNzVGFtcGVyaW5nPgoJ
PC9SdWxlR3JvdXA+CgktLT4KCgk8IS0tU1lTTU9OIEVWRU5UIElEIDI1NSA6IEVSUk9SLS0+CgkJPCEtLSJUaGlzIGV2ZW50IGlzIGdlbmVyYXRlZCB3aGVu
IGFuIGVycm9yIG9jY3VycmVkIHdpdGhpbiBTeXNtb24uIFRoZXkgY2FuIGhhcHBlbiBpZiB0aGUgc3lzdGVtIGlzIHVuZGVyIGhlYXZ5IGxvYWQKCQkJYW5k
IGNlcnRhaW4gdGFza2VkIGNvdWxkIG5vdCBiZSBwZXJmb3JtZWQgb3IgYSBidWcgZXhpc3RzIGluIHRoZSBTeXNtb24gc2VydmljZS4gWW91IGNhbiByZXBv
cnQgYW55IGJ1Z3Mgb24gdGhlCgkJCVN5c2ludGVybmFscyBmb3J1bSBvciBvdmVyIFR3aXR0ZXIgKEBtYXJrcnVzc2lub3ZpY2gpLiItLT4KCQk8IS0tQ2Fu
bm90IGJlIGZpbHRlcmVkLi0tPgoKCTwvRXZlbnRGaWx0ZXJpbmc+CjwvU3lzbW9uPg==
'@

# Strip anything that is not a base64 character before decoding. .NET already
# ignores embedded whitespace, but the payload is re-line-ended to CRLF when it
# is staged on the VM and being explicit costs nothing.
try {
    $sysmonXmlBytes = [Convert]::FromBase64String(($SysmonConfigB64 -replace '[^A-Za-z0-9+/=]', ''))
    [System.IO.File]::WriteAllBytes($SysmonConfigPath, $sysmonXmlBytes)
    Write-Info "wrote $($sysmonXmlBytes.Length) bytes -> $SysmonConfigPath"
} catch {
    Add-Failure "could not write the Sysmon config: $($_.Exception.Message)"
}

# ============================================================================
# 2. SYSMON
# ============================================================================
# Upstream guard: `win_service: name=sysmon64` is registered and the install
# runs only `when: result.state is not defined or result.name is not defined`
# -- i.e. only when the service is not there. Mirrored exactly, which is what
# makes a redeployed or retried lane a no-op here.
Write-Step 'Installing Sysmon'
$sysmonSvc = Get-Service -Name 'Sysmon64' -ErrorAction SilentlyContinue
if ($sysmonSvc) {
    Write-Info "Sysmon64 service already present (status: $($sysmonSvc.Status)) -- skipping install"
    if ($sysmonSvc.Status -ne 'Running') {
        try { Start-Service -Name 'Sysmon64' -ErrorAction Stop; Write-Info 'started Sysmon64' }
        catch { Write-Note "could not start Sysmon64: $($_.Exception.Message)" }
    }
} elseif ($script:Failures.Count -gt 0) {
    Write-Note 'skipping Sysmon install because its config could not be written'
} else {
    $sysmonZip = Join-Path $SysmonDir 'Sysmon.zip'
    if (Get-RemoteFile -Url $SysmonZipUrl -OutFile $sysmonZip) {
        try {
            Expand-Archive -Path $sysmonZip -DestinationPath $SysmonDir -Force
            Write-Info "extracted to $SysmonDir"
        } catch {
            Add-Failure "could not extract Sysmon.zip: $($_.Exception.Message)"
        }

        $sysmonExe = Join-Path $SysmonDir 'Sysmon64.exe'
        if (Test-Path $sysmonExe) {
            Write-Info "running: Sysmon64.exe -accepteula -i $SysmonConfigPath"
            # Native stderr is merged so a refusal shows up in the deployment
            # UI transcript rather than vanishing.
            & $sysmonExe -accepteula -i $SysmonConfigPath 2>&1 | ForEach-Object { Write-Info $_ }
            $rc = $LASTEXITCODE
            Start-Sleep -Seconds 3
            $sysmonSvc = Get-Service -Name 'Sysmon64' -ErrorAction SilentlyContinue
            if ($sysmonSvc) {
                Write-Info "Sysmon64 installed (service status: $($sysmonSvc.Status), installer exit $rc)"
            } else {
                Add-Failure "Sysmon64.exe exited $rc and no Sysmon64 service exists"
            }
        } else {
            Add-Failure "Sysmon64.exe not found under $SysmonDir after extraction"
        }
    } else {
        Add-Failure "could not download Sysmon from $SysmonZipUrl"
    }
}

# ============================================================================
# 3. WINLOGBEAT
# ============================================================================
Write-Step "Installing Winlogbeat $WinlogbeatVersion"
if (-not (Test-Path $InstallRoot)) {
    New-Item -ItemType Directory -Path $InstallRoot -Force | Out-Null
}

$wlbSvc         = Get-Service -Name 'winlogbeat' -ErrorAction SilentlyContinue
$versionPresent = Test-Path $VersionDir

if ($wlbSvc -and $versionPresent) {
    Write-Info "winlogbeat $WinlogbeatVersion already installed (service status: $($wlbSvc.Status))"
}

# Upstream tasks/winlogbeat.yml: a service that exists while the VERSIONED
# folder does not means an older beat is installed -- it copies and runs
# files/uninstall-service-winlogbeat.ps1 before laying down the new one. That
# script is 6 lines; reproduced inline rather than shipping a second file.
if ($wlbSvc -and -not $versionPresent) {
    Write-Info 'a different winlogbeat version is installed -- removing its service first'
    try {
        $wmiSvc = Get-WmiObject -Class Win32_Service -Filter "name='winlogbeat'" -ErrorAction Stop
        if ($wmiSvc) {
            $wmiSvc.StopService() | Out-Null
            Start-Sleep -Seconds 1
            $wmiSvc.delete() | Out-Null
            Write-Info 'old winlogbeat service deleted'
        }
    } catch {
        Write-Note "could not remove the old winlogbeat service: $($_.Exception.Message)"
    }
    $wlbSvc = $null
}

if (-not $versionPresent) {
    $beatZip = Join-Path $InstallRoot 'winlogbeat.zip'
    if (Get-RemoteFile -Url $BeatUrl -OutFile $beatZip) {
        try {
            Expand-Archive -Path $beatZip -DestinationPath $InstallRoot -Force
            Remove-Item $beatZip -Force -ErrorAction SilentlyContinue
            $versionPresent = Test-Path $VersionDir
            Write-Info "extracted to $VersionDir"
        } catch {
            Add-Failure "could not extract the winlogbeat archive: $($_.Exception.Message)"
        }
    } else {
        Add-Failure "could not download winlogbeat from $BeatUrl"
    }

    # Upstream's "Remove other winlogbeat installations" step. Narrowed to
    # directories that actually look like a winlogbeat install so a stray file
    # under the install root is not swept up with them.
    if ($versionPresent) {
        Get-ChildItem -Path $InstallRoot -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -like 'winlogbeat-*' -and $_.Name -ne $VersionDirName } |
            ForEach-Object {
                Write-Info "removing stale install $($_.FullName)"
                Remove-Item $_.FullName -Recurse -Force -ErrorAction SilentlyContinue
            }
    }
}

# ---------------------------------------------------------------------------
# 3a. The config -- a faithful port of templates/winlogbeat.yml.j2
# ---------------------------------------------------------------------------
# EVERY event_logs entry from the template is reproduced below. Those entries
# ARE the extension: Security with the security js processor, Sysmon with the
# sysmon processor, both PowerShell channels (400/403/600/800 and the 4103-4106
# script-block logging that catches obfuscated payloads), ForwardedEvents with
# its per-channel processor selection, and WMI-Activity 5857-5861. Dropping any
# of them silently removes a whole class of detection from the lane.
#
# Differences from upstream, and only these:
#   - hosts is a NAME (see the header), not hostvars['elk'].ansible_host
#   - NO username/password (see the header)
#
# A single-quoted here-string, because the ${path.home} references in the
# processor file paths are winlogbeat's own variable syntax and PowerShell must
# not expand them. The host is substituted afterwards with a literal replace.
$WinlogbeatYaml = @'
###############################################################################
# Winlogbeat configuration -- CyberCore lane agent
#
# Rendered by the goad-elk-agent post-clone script from GOAD's
# extensions/elk/ansible/roles/logs_windows/templates/winlogbeat.yml.j2.
# Edit that script, not this file: the next deploy overwrites this.
###############################################################################

# ======================== Winlogbeat specific options ========================
winlogbeat.event_logs:
  - name: Application
    ignore_older: 30m

  - name: System

  - name: Security
    processors:
      - script:
          lang: javascript
          id: security
          file: ${path.home}/module/security/config/winlogbeat-security.js

  - name: Microsoft-Windows-Sysmon/Operational
    processors:
      - script:
          lang: javascript
          id: sysmon
          file: ${path.home}/module/sysmon/config/winlogbeat-sysmon.js

  - name: Windows PowerShell
    event_id: 400, 403, 600, 800
    processors:
      - script:
          lang: javascript
          id: powershell
          file: ${path.home}/module/powershell/config/winlogbeat-powershell.js

  - name: Microsoft-Windows-PowerShell/Operational
    event_id: 4103, 4104, 4105, 4106
    processors:
      - script:
          lang: javascript
          id: powershell
          file: ${path.home}/module/powershell/config/winlogbeat-powershell.js

  - name: ForwardedEvents
    tags: [forwarded]
    processors:
      - script:
          when.equals.winlog.channel: Security
          lang: javascript
          id: security
          file: ${path.home}/module/security/config/winlogbeat-security.js
      - script:
          when.equals.winlog.channel: Microsoft-Windows-Sysmon/Operational
          lang: javascript
          id: sysmon
          file: ${path.home}/module/sysmon/config/winlogbeat-sysmon.js
      - script:
          when.equals.winlog.channel: Windows PowerShell
          lang: javascript
          id: powershell
          file: ${path.home}/module/powershell/config/winlogbeat-powershell.js
      - script:
          when.equals.winlog.channel: Microsoft-Windows-PowerShell/Operational
          lang: javascript
          id: powershell
          file: ${path.home}/module/powershell/config/winlogbeat-powershell.js

  - name: Microsoft-Windows-WMI-Activity/Operational
    event_id: 5857,5858,5859,5860,5861

# ====================== Elasticsearch template settings ======================
setup.template.settings:
  index.number_of_shards: 1

# =================================== Kibana ==================================
# Inert on a lane agent: it is only read by `winlogbeat setup`, which this
# install deliberately never runs -- the sealed ELK template already carries
# the index template, the ILM policy and the dashboards that setup would push.
# Kept so the file stays recognisable against the upstream template.
setup.kibana:
  host: "__ELK_HOST__"

# ================================== Outputs ==================================
# A NAME, not an IP: the lane gateway publishes __ELK_HOST__ as a dnsmasq
# host-record for this lane's own elk machine, so the agent does not care which
# octet the SIEM landed on.
#
# NO username/password. Upstream hardcodes elastic/changeme, which only works
# with security enabled and the default password unchanged. GOAD's stack is
# Elasticsearch 7.x with security off, so credentials here would be wrong in
# both directions.
output.elasticsearch:
  hosts: ["__ELK_HOST__:__ELK_PORT__"]

# ================================= Processors ================================
processors:
  - add_host_metadata:
      when.not.contains.tags: forwarded
  - add_cloud_metadata: ~
'@

if ($versionPresent) {
    $yamlPath = Join-Path $VersionDir 'winlogbeat.yml'
    $rendered = $WinlogbeatYaml.Replace('__ELK_HOST__', $ElkHost).Replace('__ELK_PORT__', [string]$ElkPort)

    $configChanged = $true
    if (Test-Path $yamlPath) {
        try {
            if ([System.IO.File]::ReadAllText($yamlPath) -ceq $rendered) { $configChanged = $false }
        } catch { }
    }

    if ($configChanged) {
        try {
            # UTF-8 WITHOUT a BOM. Set-Content -Encoding UTF8 on PowerShell 5.1
            # writes one, and the Go YAML parser inside the beat treats a
            # leading BOM as content and refuses to start.
            $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
            [System.IO.File]::WriteAllText($yamlPath, $rendered, $utf8NoBom)
            Write-Info "wrote config -> $yamlPath"
        } catch {
            Add-Failure "could not write winlogbeat.yml: $($_.Exception.Message)"
            $configChanged = $false
        }
    } else {
        Write-Info 'config already current -- left alone'
    }

    # ---- register the service ---------------------------------------------
    $wlbSvc = Get-Service -Name 'winlogbeat' -ErrorAction SilentlyContinue
    if (-not $wlbSvc) {
        $installer = Join-Path $VersionDir 'install-service-winlogbeat.ps1'
        if (Test-Path $installer) {
            Write-Info 'running install-service-winlogbeat.ps1'
            # -ExecutionPolicy Bypass so the shipped installer runs regardless
            # of whatever policy the base image was baked with.
            & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $installer 2>&1 |
                ForEach-Object { Write-Info $_ }
            Start-Sleep -Seconds 2
            $wlbSvc = Get-Service -Name 'winlogbeat' -ErrorAction SilentlyContinue
        } else {
            Add-Failure "install-service-winlogbeat.ps1 missing from $VersionDir"
        }
    }

    # ---- start it ----------------------------------------------------------
    #
    # NO `winlogbeat setup`, NO REBOOT. See the header -- both are upstream
    # steps that the sealed ELK template makes redundant, and the reboot would
    # drop a lane VM mid-deploy.
    if ($wlbSvc) {
        try { Set-Service -Name 'winlogbeat' -StartupType Automatic -ErrorAction Stop } catch {
            Write-Note "could not set winlogbeat to automatic start: $($_.Exception.Message)"
        }
        try {
            $wlbSvc.Refresh()
            if ($wlbSvc.Status -ne 'Running') {
                Start-Service -Name 'winlogbeat' -ErrorAction Stop
                Write-Info 'winlogbeat service started'
            } elseif ($configChanged) {
                Restart-Service -Name 'winlogbeat' -Force -ErrorAction Stop
                Write-Info 'winlogbeat service restarted to pick up the new config'
            } else {
                Write-Info 'winlogbeat service already running'
            }
        } catch {
            Add-Failure "could not start the winlogbeat service: $($_.Exception.Message)"
        }
    } else {
        Add-Failure 'the winlogbeat service does not exist after installation'
    }
} else {
    Write-Note 'winlogbeat is not installed -- skipping config and service steps'
}

# ============================================================================
# 4. REACHABILITY -- REPORTED, NEVER ENFORCED
# ============================================================================
# This probe exists so the deployment transcript says whether the SIEM was up
# at install time, and NOTHING ELSE DEPENDS ON IT. Post-clone scripts routinely
# run before the lane's ELK VM has finished booting; winlogbeat retries its
# output forever, so an unreachable ELK now is a healthy lane in ten minutes.
# Failing here would mark a perfectly good lane as failed.
Write-Step 'Checking ELK reachability (informational only)'
try {
    $addrs = [System.Net.Dns]::GetHostAddresses($ElkHost) | ForEach-Object { $_.IPAddressToString }
    Write-Info "$ElkHost resolves to: $($addrs -join ', ')"
} catch {
    Write-Info "$ElkHost does not resolve yet -- the lane gateway publishes this host-record; winlogbeat will keep retrying"
}
if (Test-TcpPort -HostName $ElkHost -Port $ElkPort) {
    Write-Info "TCP ${ElkHost}:${ElkPort} is open -- events should start flowing immediately"
} else {
    Write-Info "TCP ${ElkHost}:${ElkPort} is not answering yet. This is EXPECTED when the SIEM VM is still booting."
    Write-Info 'Winlogbeat spools locally and reconnects on its own; no action is required and this is not a failure.'
}

# ============================================================================
# SUMMARY
# ============================================================================
Write-Host ''
Write-Host '=== goad-elk-agent complete ==='
$sysmonSvc = Get-Service -Name 'Sysmon64'   -ErrorAction SilentlyContinue
$wlbSvc    = Get-Service -Name 'winlogbeat' -ErrorAction SilentlyContinue
Write-Info ("Sysmon64    : " + $(if ($sysmonSvc) { $sysmonSvc.Status } else { 'NOT INSTALLED' }))
Write-Info ("winlogbeat  : " + $(if ($wlbSvc)    { $wlbSvc.Status }    else { 'NOT INSTALLED' }))
Write-Info "Config      : $VersionDir\winlogbeat.yml"
Write-Info "Output      : ${ElkHost}:${ElkPort} (no credentials, security off -- 7.x stack)"
Write-Info "Sysmon cfg  : $SysmonConfigPath (SwiftOnSecurity, embedded)"
Write-Info "Finished    : $(Get-Date -Format 'u')"

if ($script:Failures.Count -gt 0) {
    Write-Host ''
    Write-Host "FAILED: $($script:Failures.Count) installation step(s) did not complete:"
    foreach ($f in $script:Failures) { Write-Host "  - $f" }
    # Non-zero ONLY for installation failures. executeScriptsOnVM marks this one
    # script failed and carries on with the rest of the deploy, so this buys
    # visibility without costing the lane.
    exit 1
}

exit 0
